#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.zombreath)]
    public class Zombreath : EffectBehaviour, IBeBlownBehaviour
    {
        #region 公有方法
        public Zombreath(string nsp, string name) : base(nsp, name)
        {
        }
        #endregion
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.TriggerAnimation("Appear");
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (entity.Timeout == 15)
            {
                entity.TriggerAnimation("Explode");
            }
        }
        public override void PostRemove(Entity entity)
        {
            base.PostRemove(entity);
            Explosion.Spawn(entity, entity.GetCenter(), 80)?.Let(e =>
            {
                e.SetTint(new Color(0, 197, 255));
            });
            
            for (int i = -1; i <= 1; i++)
            {
                var param = entity.GetSpawnParams();
                param.SetProperty(VanillaEntityProps.DAMAGE, entity.GetDamage());
                var grid1 = entity.Level.GetGrid(entity.GetColumn() + i, entity.GetLane());
                if (grid1 != null)
                {
                    GridFire.Spawn(grid1, entity, param);
                }
                var grid2 = entity.Level.GetGrid(entity.GetColumn(), entity.GetLane() + i);
                if (grid2 != null)
                {
                    GridFire.Spawn(grid2, entity, param);
                }
            }
            entity.PlaySound(VanillaSoundID.explosion);
            entity.PlaySound(VanillaSoundID.impact);
        }
        public void BeBlown(Entity entity, Entity source)
        {
            var newVelocity = source.IsFacingLeft() ? Vector3.left : Vector3.right;
            entity.Position += newVelocity * 3;
        }
    }
}